--
-- Name: mission_templates; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.mission_templates (
    key character varying(80) NOT NULL,
    scope character varying(12) NOT NULL,
    template character varying(40) NOT NULL,
    title text NOT NULL,
    description text NOT NULL,
    target_count integer NOT NULL,
    quiz_pass_percent integer DEFAULT 70 NOT NULL,
    reward_xp integer DEFAULT 0 NOT NULL,
    reward_peak integer DEFAULT 0 NOT NULL,
    coupon_max_percent integer,
    coupon_valid_days integer,
    is_active boolean DEFAULT true NOT NULL,
    CONSTRAINT chk_mission_templates_amounts CHECK (((target_count > 0) AND (reward_xp >= 0) AND (reward_peak >= 0))),
    CONSTRAINT chk_mission_templates_coupon CHECK ((((coupon_max_percent IS NULL) AND (coupon_valid_days IS NULL)) OR ((coupon_max_percent IS NOT NULL) AND (coupon_valid_days IS NOT NULL) AND ((coupon_max_percent >= 1) AND (coupon_max_percent <= 100)) AND (coupon_valid_days > 0)))),
    CONSTRAINT chk_mission_templates_criteria CHECK (((quiz_pass_percent >= 0) AND (quiz_pass_percent <= 100) AND (((template)::text <> 'chapter.quiz_pass'::text) OR (target_count = 1)) AND (((template)::text <> 'course.weekly_streak'::text) OR (target_count <= 7)))),
    CONSTRAINT chk_mission_templates_scope CHECK (((((scope)::text = 'daily'::text) AND ((template)::text = ANY (ARRAY[('lesson.completed'::character varying)::text, ('quiz.completed'::character varying)::text, ('code.completed'::character varying)::text, ('daily_checkin.completed'::character varying)::text]))) OR (((scope)::text = 'course'::text) AND ((template)::text = ANY (ARRAY[('chapter.complete'::character varying)::text, ('chapter.quiz_pass'::character varying)::text, ('course.complete'::character varying)::text, ('course.weekly_streak'::character varying)::text])))))
);


