--
-- Name: provider_creation_requests; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.provider_creation_requests (
    id uuid DEFAULT public.uuid_generate_v4() NOT NULL,
    requester_id uuid NOT NULL,
    name character varying(160) NOT NULL,
    normalized_name character varying(160) NOT NULL,
    provider_type character varying(30) NOT NULL,
    description text NOT NULL,
    contact_email character varying(320) NOT NULL,
    website_url character varying(2048),
    reason text NOT NULL,
    status character varying(20) DEFAULT 'pending'::character varying NOT NULL,
    reviewed_by uuid,
    decided_at timestamp with time zone,
    review_note text,
    provider_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT ck_provider_request_decision CHECK (((((status)::text = 'pending'::text) AND (decided_at IS NULL) AND (reviewed_by IS NULL) AND (provider_id IS NULL)) OR (((status)::text = 'approved'::text) AND (decided_at IS NOT NULL) AND (reviewed_by IS NOT NULL) AND (provider_id IS NOT NULL)) OR (((status)::text = 'rejected'::text) AND (decided_at IS NOT NULL) AND (reviewed_by IS NOT NULL) AND (review_note IS NOT NULL) AND (length(TRIM(BOTH FROM review_note)) > 0) AND (provider_id IS NULL)) OR (((status)::text = 'cancelled'::text) AND (decided_at IS NOT NULL) AND (reviewed_by IS NULL) AND (provider_id IS NULL)))),
    CONSTRAINT ck_provider_request_status CHECK (((status)::text = ANY (ARRAY[('pending'::character varying)::text, ('approved'::character varying)::text, ('rejected'::character varying)::text, ('cancelled'::character varying)::text]))),
    CONSTRAINT ck_provider_request_type CHECK (((provider_type)::text = ANY (ARRAY[('individual'::character varying)::text, ('center'::character varying)::text, ('exam_center'::character varying)::text, ('organization'::character varying)::text, ('school'::character varying)::text])))
);


--
-- Name: provider_join_requests; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.provider_join_requests (
    id uuid DEFAULT public.uuid_generate_v4() NOT NULL,
    provider_id uuid NOT NULL,
    requester_id uuid NOT NULL,
    "position" character varying(160) NOT NULL,
    work_email character varying(254),
    evidence text NOT NULL,
    status character varying(20) DEFAULT 'pending'::character varying NOT NULL,
    review_note text,
    reviewed_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    decided_at timestamp with time zone,
    CONSTRAINT ck_provider_join_decision CHECK (((((status)::text = 'pending'::text) AND (reviewed_by IS NULL) AND (decided_at IS NULL)) OR (((status)::text = 'cancelled'::text) AND (reviewed_by IS NULL) AND (decided_at IS NOT NULL)) OR (((status)::text = ANY (ARRAY[('approved'::character varying)::text, ('rejected'::character varying)::text])) AND (reviewed_by IS NOT NULL) AND (decided_at IS NOT NULL) AND (length(TRIM(BOTH FROM review_note)) >= 10)))),
    CONSTRAINT ck_provider_join_review_not_null CHECK ((((status)::text <> ALL (ARRAY[('approved'::character varying)::text, ('rejected'::character varying)::text])) OR (review_note IS NOT NULL))),
    CONSTRAINT ck_provider_join_status CHECK (((status)::text = ANY (ARRAY[('pending'::character varying)::text, ('approved'::character varying)::text, ('rejected'::character varying)::text, ('cancelled'::character varying)::text])))
);


