    CONSTRAINT ck_provider_membership_event_actor CHECK ((((action)::text = 'legacy_imported'::text) OR (actor_id IS NOT NULL))),
    CONSTRAINT ck_provider_membership_event_reason CHECK ((((action)::text <> 'revoked'::text) OR ((reason IS NOT NULL) AND (length(TRIM(BOTH FROM reason)) > 0)))),
    CONSTRAINT ck_provider_membership_event_status CHECK (((status)::text = ANY (ARRAY[('active'::character varying)::text, ('inactive'::character varying)::text])))
);


