--
-- Name: user_digital_certificates; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.user_digital_certificates (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid,
    is_platform_ca boolean DEFAULT false NOT NULL,
    serial_number character varying(64) NOT NULL,
    subject_cn text NOT NULL,
    subject_email character varying(255),
    subject_cccd character varying(50),
    issuer_cn text DEFAULT 'Mây Mây Digital CA'::text NOT NULL,
    algorithm character varying(40) DEFAULT 'RSA-2048-SHA256'::character varying NOT NULL,
    public_key_pem text NOT NULL,
    certificate_pem text NOT NULL,
    encrypted_private_key text NOT NULL,
    key_salt character varying(128) NOT NULL,
    key_iv character varying(128) NOT NULL,
    valid_from timestamp with time zone NOT NULL,
    valid_until timestamp with time zone NOT NULL,
    status character varying(20) DEFAULT 'active'::character varying NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


