--
-- Name: user_missions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.user_missions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    mission_id uuid,
    title text NOT NULL,
    event_type character varying(100) NOT NULL,
    target_count integer DEFAULT 1 NOT NULL,
    current_count integer DEFAULT 0 NOT NULL,
    reward_xp integer DEFAULT 0 NOT NULL,
    reward_peak_wallet integer DEFAULT 0 NOT NULL,
    status character varying(50) DEFAULT 'assigned'::character varying NOT NULL,
    cycle_date date NOT NULL,
    version integer DEFAULT 1 NOT NULL,
    assigned_at timestamp with time zone DEFAULT now() NOT NULL,
    description text,
    completed_at timestamp with time zone,
    claimed_at timestamp with time zone,
    scope character varying(12),
    template character varying(40),
    template_key character varying(80),
    course_id uuid,
    section_id uuid,
    quiz_pass_percent integer,
    coupon_max_percent integer,
    coupon_valid_days integer,
    claim_result jsonb,
    CONSTRAINT chk_user_missions_scope CHECK (
CASE
    WHEN (scope IS NULL) THEN (mission_id IS NOT NULL)
    WHEN ((scope)::text = 'daily'::text) THEN ((mission_id IS NULL) AND (template_key IS NOT NULL) AND (template IS NOT NULL) AND (course_id IS NULL) AND (section_id IS NULL))
    WHEN ((scope)::text = 'course'::text) THEN ((mission_id IS NULL) AND (template_key IS NOT NULL) AND (course_id IS NOT NULL) AND (template IS NOT NULL) AND (((section_id IS NOT NULL) AND ((template)::text = ANY (ARRAY[('chapter.complete'::character varying)::text, ('chapter.quiz_pass'::character varying)::text]))) OR ((section_id IS NULL) AND ((template)::text = ANY (ARRAY[('course.complete'::character varying)::text, ('course.weekly_streak'::character varying)::text])))))
    ELSE false
END)
);


