    updated_at timestamp without time zone DEFAULT now(),
    kyc_verified boolean DEFAULT false
);


--
-- Name: TABLE wallets; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.wallets IS 'Ví người dùng (1 user = 1 ví)';


--
-- Name: COLUMN wallets.balance; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.wallets.balance IS 'Số dư hiện tại của ví';


--
-- Name: COLUMN wallets.total_in; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.wallets.total_in IS 'Tổng tiền nạp vào';


--
-- Name: COLUMN wallets.total_out; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.wallets.total_out IS 'Tổng tiền rút ra';


--
-- Name: COLUMN wallets.currency; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.wallets.currency IS 'Đơn vị tiền tệ (VND/USD)';


--
-- Name: COLUMN wallets.is_locked; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.wallets.is_locked IS 'Khóa ví khi nghi ngờ gian lận';


--
-- Name: withdrawal_requests; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.withdrawal_requests (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    lecturer_id uuid NOT NULL,
    amount numeric(12,2) NOT NULL,
    currency character varying(10) DEFAULT 'USD'::character varying NOT NULL,
    status character varying(20) NOT NULL,
    paypal_batch_id text,
    error_message text,
    requested_at timestamp with time zone DEFAULT now(),
    approved_at timestamp with time zone,
    rejected_at timestamp with time zone,
    transaction_id uuid,
    reason text,
    coin_amount integer,
    CONSTRAINT chk_withdrawal_requests_coin_amount CHECK (((coin_amount IS NULL) OR (coin_amount > 0))),
    CONSTRAINT withdrawal_requests_amount_check CHECK ((amount > (0)::numeric)),
    CONSTRAINT withdrawal_requests_status_check CHECK (((status)::text = ANY (ARRAY[('pending'::character varying)::text, ('approved'::character varying)::text, ('rejected'::character varying)::text, ('payout_pending'::character varying)::text, ('paid'::character varying)::text, ('failed'::character varying)::text, ('processing'::character varying)::text])))
);


